INSERT INTO steps (id, lesson_id, title, content, type, order_index, created_at, updated_at) VALUES
  ('aaaa0001-0003-4000-8000-000000001101', 'aaaa0001-0002-4000-8000-000000000011', 'Welcome', '{"text":"Hi! In this lesson you will learn how to greet people in English. The most common greetings are: Hello, Hi, Good morning, Good evening."}'::jsonb, 'text', 1, NOW(), NOW()),
  ('aaaa0001-0003-4000-8000-000000001102', 'aaaa0001-0002-4000-8000-000000000011', 'Match greetings', '{"type":"match_pairs","instruction":"Match each English greeting with its Russian translation","pairs":[{"left":"Hello","right":"Привет"},{"left":"Goodbye","right":"До свидания"},{"left":"Good morning","right":"Доброе утро"},{"left":"Good night","right":"Спокойной ночи"},{"left":"See you","right":"Увидимся"}]}'::jsonb, 'match_pairs', 2, NOW(), NOW()),
  ('aaaa0001-0003-4000-8000-000000001103', 'aaaa0001-0002-4000-8000-000000000011', 'Morning greeting', '{"type":"quiz","instruction":"Choose the correct answer","question":"What do you say to someone at 9 AM?","options":[{"text":"Good morning","is_correct":true},{"text":"Good night","is_correct":false},{"text":"Goodbye","is_correct":false},{"text":"See you tomorrow","is_correct":false}],"explanation":"Good morning is used until about noon."}'::jsonb, 'quiz', 3, NOW(), NOW()),
  ('aaaa0001-0003-4000-8000-000000001104', 'aaaa0001-0002-4000-8000-000000000011', 'Translate: Hello, friend', '{"type":"translate","instruction":"Translate the phrase to Russian","source_text":"Hello, my friend!","source_language":"en","target_language":"ru","correct_translation":"Привет, мой друг!","alternative_answers":["Здравствуй, мой друг!","Привет мой друг"],"word_bank":["Привет",",","мой","друг","!","Пока","до"],"hints":["friend = друг"]}'::jsonb, 'translate', 4, NOW(), NOW()),
  ('aaaa0001-0003-4000-8000-000000001105', 'aaaa0001-0002-4000-8000-000000000011', 'Fill the goodbye', '{"type":"fill_blank","instruction":"Complete the goodbye phrase","sentence_template":"___ night! Sleep well.","options":["Good","Bad","Hello","Hi"],"correct_answer":"Good","alternatives":[],"explanation":"''Good night'' is said before sleep."}'::jsonb, 'fill_blank', 5, NOW(), NOW()),
  ('aaaa0001-0003-4000-8000-000000001201', 'aaaa0001-0002-4000-8000-000000000012', 'How to introduce yourself', '{"text":"To introduce yourself in English say: ''My name is …'' or ''I am …''. To ask the other person: ''What is your name?''"}'::jsonb, 'text', 1, NOW(), NOW()),
  ('aaaa0001-0003-4000-8000-000000001202', 'aaaa0001-0002-4000-8000-000000000012', 'Complete the introduction', '{"type":"fill_blank","instruction":"Fill in the blank","sentence_template":"My ___ is Anna.","options":["name","age","city","friend"],"correct_answer":"name","alternatives":[],"explanation":"''My name is …'' is the standard form."}'::jsonb, 'fill_blank', 2, NOW(), NOW()),
  ('aaaa0001-0003-4000-8000-000000001203', 'aaaa0001-0002-4000-8000-000000000012', 'Translate: I am Alex', '{"type":"translate","instruction":"Translate to Russian","source_text":"I am Alex. Nice to meet you.","source_language":"en","target_language":"ru","correct_translation":"Я Алекс. Приятно познакомиться.","alternative_answers":["Я — Алекс. Приятно познакомиться."],"word_bank":["Я","Алекс",".","Приятно","познакомиться","Привет","имя"],"hints":[]}'::jsonb, 'translate', 3, NOW(), NOW()),
  ('aaaa0001-0003-4000-8000-000000001204', 'aaaa0001-0002-4000-8000-000000000012', 'Listen: name', '{"type":"listening","instruction":"Type what you hear","audio_text":"My name is John","language":"en","audio_url":"","translation_hint":"Меня зовут Джон","alternative_answers":["my name is john","My name is John."]}'::jsonb, 'listening', 4, NOW(), NOW()),
  ('aaaa0001-0003-4000-8000-000000001205', 'aaaa0001-0002-4000-8000-000000000012', 'Asking a name', '{"type":"quiz","instruction":"Choose the correct answer","question":"How do you ask someone''s name?","options":[{"text":"What is your name?","is_correct":true},{"text":"How old are you?","is_correct":false},{"text":"Where are you from?","is_correct":false},{"text":"How are you?","is_correct":false}],"explanation":"''What is your name?'' asks for the name."}'::jsonb, 'quiz', 5, NOW(), NOW()),
  ('aaaa0001-0003-4000-8000-000000001301', 'aaaa0001-0002-4000-8000-000000000013', 'Talking about countries', '{"text":"To say where you are from, use ''I am from + country''. Example: I am from Russia. I am from Kazakhstan. To ask: Where are you from?"}'::jsonb, 'text', 1, NOW(), NOW()),
  ('aaaa0001-0003-4000-8000-000000001302', 'aaaa0001-0002-4000-8000-000000000013', 'Match countries', '{"type":"match_pairs","instruction":"Match the country with its translation","pairs":[{"left":"Russia","right":"Россия"},{"left":"Kazakhstan","right":"Казахстан"},{"left":"the USA","right":"США"},{"left":"the UK","right":"Великобритания"},{"left":"Germany","right":"Германия"}]}'::jsonb, 'match_pairs', 2, NOW(), NOW()),
  ('aaaa0001-0003-4000-8000-000000001303', 'aaaa0001-0002-4000-8000-000000000013', 'Country sentence', '{"type":"fill_blank","instruction":"Complete the sentence","sentence_template":"I am ___ Kazakhstan.","options":["from","in","to","at"],"correct_answer":"from","alternatives":[],"explanation":"''from'' indicates origin."}'::jsonb, 'fill_blank', 3, NOW(), NOW()),
  ('aaaa0001-0003-4000-8000-000000001304', 'aaaa0001-0002-4000-8000-000000000013', 'Translate: from Russia', '{"type":"translate","instruction":"Translate to Russian","source_text":"I am from Russia.","source_language":"en","target_language":"ru","correct_translation":"Я из России.","alternative_answers":["Я — из России."],"word_bank":["Я","из","России",".","в","США"],"hints":[]}'::jsonb, 'translate', 4, NOW(), NOW()),
  ('aaaa0001-0003-4000-8000-000000001305', 'aaaa0001-0002-4000-8000-000000000013', 'Nationality', '{"type":"quiz","instruction":"Choose the correct answer","question":"A person from Germany is …","options":[{"text":"German","is_correct":true},{"text":"Germanian","is_correct":false},{"text":"Germany","is_correct":false},{"text":"Germanic","is_correct":false}],"explanation":"Nationality of Germany is ''German''."}'::jsonb, 'quiz', 5, NOW(), NOW()),
  ('aaaa0001-0003-4000-8000-000000001401', 'aaaa0001-0002-4000-8000-000000000014', 'Asking how someone is', '{"text":"Common phrases: How are you? — I am fine, thanks. And you? Use ''fine'' / ''good'' / ''great'' / ''so-so''."}'::jsonb, 'text', 1, NOW(), NOW()),
  ('aaaa0001-0003-4000-8000-000000001402', 'aaaa0001-0002-4000-8000-000000000014', 'Match responses', '{"type":"match_pairs","instruction":"Match phrase and translation","pairs":[{"left":"I am fine","right":"Я в порядке"},{"left":"Not bad","right":"Неплохо"},{"left":"So-so","right":"Так себе"},{"left":"Great!","right":"Отлично!"},{"left":"Thank you","right":"Спасибо"}]}'::jsonb, 'match_pairs', 2, NOW(), NOW()),
  ('aaaa0001-0003-4000-8000-000000001403', 'aaaa0001-0002-4000-8000-000000000014', 'Reply politely', '{"type":"fill_blank","instruction":"Complete the polite reply","sentence_template":"I am fine, ___ you.","options":["thank","please","sorry","hello"],"correct_answer":"thank","alternatives":[],"explanation":"''Thank you'' is a polite phrase."}'::jsonb, 'fill_blank', 3, NOW(), NOW()),
  ('aaaa0001-0003-4000-8000-000000001404', 'aaaa0001-0002-4000-8000-000000000014', 'Listen: how are you', '{"type":"listening","instruction":"Type what you hear","audio_text":"How are you today","language":"en","audio_url":"","translation_hint":"Как ты сегодня?","alternative_answers":["how are you today","How are you today?"]}'::jsonb, 'listening', 4, NOW(), NOW()),
  ('aaaa0001-0003-4000-8000-000000001405', 'aaaa0001-0002-4000-8000-000000000014', 'Polite question', '{"type":"quiz","instruction":"Choose the correct answer","question":"After ''I am fine, thanks'', what is polite to add?","options":[{"text":"And you?","is_correct":true},{"text":"Goodbye!","is_correct":false},{"text":"Sorry.","is_correct":false},{"text":"No.","is_correct":false}],"explanation":"''And you?'' returns the question."}'::jsonb, 'quiz', 5, NOW(), NOW()),
  ('aaaa0001-0003-4000-8000-000000001501', 'aaaa0001-0002-4000-8000-000000000015', 'Polite expressions', '{"text":"When you meet someone for the first time say: ''Nice to meet you.'' Reply: ''Nice to meet you too.''"}'::jsonb, 'text', 1, NOW(), NOW()),
  ('aaaa0001-0003-4000-8000-000000001502', 'aaaa0001-0002-4000-8000-000000000015', 'Tap: meet you', '{"type":"tap_words","instruction":"Tap the words you hear, in order","audio_url":"","audio_text":"Nice to meet you","word_bank":["Nice","to","meet","you","see","again","hello","name"],"correct_words":["Nice","to","meet","you"]}'::jsonb, 'tap_words', 2, NOW(), NOW()),
  ('aaaa0001-0003-4000-8000-000000001503', 'aaaa0001-0002-4000-8000-000000000015', 'Translate: meet you too', '{"type":"translate","instruction":"Translate to Russian","source_text":"Nice to meet you too.","source_language":"en","target_language":"ru","correct_translation":"Мне тоже приятно познакомиться.","alternative_answers":["И мне приятно познакомиться."],"word_bank":["Мне","тоже","приятно","познакомиться",".","очень"],"hints":[]}'::jsonb, 'translate', 3, NOW(), NOW()),
  ('aaaa0001-0003-4000-8000-000000001504', 'aaaa0001-0002-4000-8000-000000000015', 'Fill the meeting phrase', '{"type":"fill_blank","instruction":"Complete the phrase","sentence_template":"Nice ___ meet you.","options":["to","for","of","at"],"correct_answer":"to","alternatives":[],"explanation":"''Nice to meet you'' — fixed phrase."}'::jsonb, 'fill_blank', 4, NOW(), NOW()),
  ('aaaa0001-0003-4000-8000-000000001505', 'aaaa0001-0002-4000-8000-000000000015', 'Meeting at a party', '{"type":"story","title":"Meeting at a party","scenes":[{"image_url":"","character":"Anna","text":"Hi! I am Anna.","translation":"Привет! Я Анна."},{"image_url":"","character":"You","text":"Hello, Anna! I am Sam.","translation":"Привет, Анна! Я Сэм."},{"type":"choice","question":"What do you say next?","options":[{"text":"Nice to meet you!","is_correct":true},{"text":"Goodbye!","is_correct":false},{"text":"How old are you?","is_correct":false}]}]}'::jsonb, 'story', 5, NOW(), NOW()),
  ('aaaa0001-0003-4000-8000-000000002101', 'aaaa0001-0002-4000-8000-000000000021', 'Counting 1 to 10', '{"text":"1 one, 2 two, 3 three, 4 four, 5 five, 6 six, 7 seven, 8 eight, 9 nine, 10 ten."}'::jsonb, 'text', 1, NOW(), NOW()),
  ('aaaa0001-0003-4000-8000-000000002102', 'aaaa0001-0002-4000-8000-000000000021', 'Match numbers', '{"type":"match_pairs","instruction":"Match digit and English word","pairs":[{"left":"1","right":"one"},{"left":"3","right":"three"},{"left":"5","right":"five"},{"left":"7","right":"seven"},{"left":"10","right":"ten"}]}'::jsonb, 'match_pairs', 2, NOW(), NOW()),
  ('aaaa0001-0003-4000-8000-000000002103', 'aaaa0001-0002-4000-8000-000000000021', 'Next number', '{"type":"fill_blank","instruction":"Complete the sequence","sentence_template":"one, two, ___, four","options":["three","five","ten","six"],"correct_answer":"three","alternatives":[],"explanation":""}'::jsonb, 'fill_blank', 3, NOW(), NOW()),
  ('aaaa0001-0003-4000-8000-000000002104', 'aaaa0001-0002-4000-8000-000000000021', 'Listen: number seven', '{"type":"listening","instruction":"Type what you hear","audio_text":"seven","language":"en","audio_url":"","translation_hint":"семь","alternative_answers":["seven","Seven","7"]}'::jsonb, 'listening', 4, NOW(), NOW()),
  ('aaaa0001-0003-4000-8000-000000002105', 'aaaa0001-0002-4000-8000-000000000021', 'How many?', '{"type":"quiz","instruction":"Choose the correct answer","question":"How do you say ''8'' in English?","options":[{"text":"eight","is_correct":true},{"text":"ate","is_correct":false},{"text":"eit","is_correct":false},{"text":"ait","is_correct":false}],"explanation":""}'::jsonb, 'quiz', 5, NOW(), NOW()),
  ('aaaa0001-0003-4000-8000-000000002201', 'aaaa0001-0002-4000-8000-000000000022', 'Tens', '{"text":"11 eleven, 12 twelve, 13 thirteen, 20 twenty, 30 thirty, 40 forty, 50 fifty, 100 one hundred. Составные: 21 twenty-one, 35 thirty-five."}'::jsonb, 'text', 1, NOW(), NOW()),
  ('aaaa0001-0003-4000-8000-000000002202', 'aaaa0001-0002-4000-8000-000000000022', 'Match tens', '{"type":"match_pairs","instruction":"Match number and English","pairs":[{"left":"20","right":"twenty"},{"left":"30","right":"thirty"},{"left":"40","right":"forty"},{"left":"50","right":"fifty"},{"left":"100","right":"one hundred"}]}'::jsonb, 'match_pairs', 2, NOW(), NOW()),
  ('aaaa0001-0003-4000-8000-000000002203', 'aaaa0001-0002-4000-8000-000000000022', 'Compose 25', '{"type":"fill_blank","instruction":"Complete the number twenty-five","sentence_template":"twenty-___","options":["five","four","six","seven"],"correct_answer":"five","alternatives":[],"explanation":""}'::jsonb, 'fill_blank', 3, NOW(), NOW()),
  ('aaaa0001-0003-4000-8000-000000002204', 'aaaa0001-0002-4000-8000-000000000022', 'Translate the number', '{"type":"translate","instruction":"Translate to Russian","source_text":"I am twenty years old.","source_language":"en","target_language":"ru","correct_translation":"Мне двадцать лет.","alternative_answers":["Мне 20 лет."],"word_bank":["Мне","двадцать","лет",".","годов","20"],"hints":[]}'::jsonb, 'translate', 4, NOW(), NOW()),
  ('aaaa0001-0003-4000-8000-000000002205', 'aaaa0001-0002-4000-8000-000000000022', 'Tricky teen', '{"type":"quiz","instruction":"Choose the correct answer","question":"Which is THIRTEEN?","options":[{"text":"13","is_correct":true},{"text":"30","is_correct":false},{"text":"33","is_correct":false},{"text":"3","is_correct":false}],"explanation":"thirteen = 13, thirty = 30."}'::jsonb, 'quiz', 5, NOW(), NOW()),
  ('aaaa0001-0003-4000-8000-000000002301', 'aaaa0001-0002-4000-8000-000000000023', 'Seven days', '{"text":"Monday, Tuesday, Wednesday, Thursday, Friday, Saturday, Sunday. The week starts on Monday."}'::jsonb, 'text', 1, NOW(), NOW()),
  ('aaaa0001-0003-4000-8000-000000002302', 'aaaa0001-0002-4000-8000-000000000023', 'Match weekdays', '{"type":"match_pairs","instruction":"Match day and translation","pairs":[{"left":"Monday","right":"Понедельник"},{"left":"Wednesday","right":"Среда"},{"left":"Friday","right":"Пятница"},{"left":"Saturday","right":"Суббота"},{"left":"Sunday","right":"Воскресенье"}]}'::jsonb, 'match_pairs', 2, NOW(), NOW()),
  ('aaaa0001-0003-4000-8000-000000002303', 'aaaa0001-0002-4000-8000-000000000023', 'Day after Monday', '{"type":"fill_blank","instruction":"Complete the sequence","sentence_template":"Monday, ___, Wednesday","options":["Tuesday","Thursday","Sunday","Saturday"],"correct_answer":"Tuesday","alternatives":[],"explanation":""}'::jsonb, 'fill_blank', 3, NOW(), NOW()),
  ('aaaa0001-0003-4000-8000-000000002304', 'aaaa0001-0002-4000-8000-000000000023', 'Tap weekdays in order', '{"type":"tap_words","instruction":"Tap the first three days of the week, in order","audio_url":"","audio_text":"Monday Tuesday Wednesday","word_bank":["Monday","Tuesday","Wednesday","Friday","Sunday","Saturday"],"correct_words":["Monday","Tuesday","Wednesday"]}'::jsonb, 'tap_words', 4, NOW(), NOW()),
  ('aaaa0001-0003-4000-8000-000000002305', 'aaaa0001-0002-4000-8000-000000000023', 'Weekend', '{"type":"quiz","instruction":"Choose the correct answer","question":"Which days are the weekend?","options":[{"text":"Saturday and Sunday","is_correct":true},{"text":"Friday and Saturday","is_correct":false},{"text":"Sunday and Monday","is_correct":false},{"text":"Wednesday and Thursday","is_correct":false}],"explanation":""}'::jsonb, 'quiz', 5, NOW(), NOW()),
  ('aaaa0001-0003-4000-8000-000000002401', 'aaaa0001-0002-4000-8000-000000000024', 'Telling time', '{"text":"Use ''It is …'' to tell time. Examples: It is 3 o''clock. It is half past two. It is a quarter to five."}'::jsonb, 'text', 1, NOW(), NOW()),
  ('aaaa0001-0003-4000-8000-000000002402', 'aaaa0001-0002-4000-8000-000000000024', 'Time phrase', '{"type":"fill_blank","instruction":"Complete the sentence","sentence_template":"It ___ five o''clock.","options":["is","are","am","be"],"correct_answer":"is","alternatives":[],"explanation":""}'::jsonb, 'fill_blank', 2, NOW(), NOW()),
  ('aaaa0001-0003-4000-8000-000000002403', 'aaaa0001-0002-4000-8000-000000000024', 'Translate: half past two', '{"type":"translate","instruction":"Translate to Russian","source_text":"It is half past two.","source_language":"en","target_language":"ru","correct_translation":"Половина третьего.","alternative_answers":["Полтретьего."],"word_bank":["Половина","третьего",".","пять","часов"],"hints":[]}'::jsonb, 'translate', 3, NOW(), NOW()),
  ('aaaa0001-0003-4000-8000-000000002404', 'aaaa0001-0002-4000-8000-000000000024', 'Listen: time', '{"type":"listening","instruction":"Type what you hear","audio_text":"It is three o''clock","language":"en","audio_url":"","translation_hint":"Сейчас три часа","alternative_answers":["it is three o''clock","It is three o''clock.","it''s three o''clock"]}'::jsonb, 'listening', 4, NOW(), NOW()),
  ('aaaa0001-0003-4000-8000-000000002405', 'aaaa0001-0002-4000-8000-000000000024', 'Quarter past', '{"type":"quiz","instruction":"Choose the correct answer","question":"What does ''a quarter past four'' mean?","options":[{"text":"4:15","is_correct":true},{"text":"3:45","is_correct":false},{"text":"4:45","is_correct":false},{"text":"4:30","is_correct":false}],"explanation":""}'::jsonb, 'quiz', 5, NOW(), NOW()),
  ('aaaa0001-0003-4000-8000-000000002501', 'aaaa0001-0002-4000-8000-000000000025', 'Parts of the day', '{"text":"in the morning, in the afternoon, in the evening, at night. Example: I work in the morning."}'::jsonb, 'text', 1, NOW(), NOW()),
  ('aaaa0001-0003-4000-8000-000000002502', 'aaaa0001-0002-4000-8000-000000000025', 'Match parts of day', '{"type":"match_pairs","instruction":"Match phrase and translation","pairs":[{"left":"morning","right":"утро"},{"left":"afternoon","right":"день"},{"left":"evening","right":"вечер"},{"left":"night","right":"ночь"},{"left":"noon","right":"полдень"}]}'::jsonb, 'match_pairs', 2, NOW(), NOW()),
  ('aaaa0001-0003-4000-8000-000000002503', 'aaaa0001-0002-4000-8000-000000000025', 'When do you work?', '{"type":"fill_blank","instruction":"Complete the time-of-day phrase","sentence_template":"I work ___ the morning.","options":["in","on","at","to"],"correct_answer":"in","alternatives":[],"explanation":"''in the morning'' is fixed."}'::jsonb, 'fill_blank', 3, NOW(), NOW()),
  ('aaaa0001-0003-4000-8000-000000002504', 'aaaa0001-0002-4000-8000-000000000025', 'Translate: in the evening', '{"type":"translate","instruction":"Translate to Russian","source_text":"I read in the evening.","source_language":"en","target_language":"ru","correct_translation":"Я читаю вечером.","alternative_answers":["По вечерам я читаю."],"word_bank":["Я","читаю","вечером",".","утром","ночью"],"hints":[]}'::jsonb, 'translate', 4, NOW(), NOW()),
  ('aaaa0001-0003-4000-8000-000000002505', 'aaaa0001-0002-4000-8000-000000000025', 'A day with Anna', '{"type":"story","title":"A day with Anna","scenes":[{"image_url":"","character":"Narrator","text":"It is 7 in the morning.","translation":"Сейчас 7 утра."},{"image_url":"","character":"Anna","text":"Good morning! I drink coffee.","translation":"Доброе утро! Я пью кофе."},{"type":"choice","question":"When does Anna drink coffee?","options":[{"text":"In the morning","is_correct":true},{"text":"At night","is_correct":false},{"text":"In the evening","is_correct":false}]}]}'::jsonb, 'story', 5, NOW(), NOW()),
  ('aaaa0001-0003-4000-8000-000000003101', 'aaaa0001-0002-4000-8000-000000000031', 'Family words', '{"text":"mother, father, brother, sister, son, daughter, grandmother, grandfather, parents, children."}'::jsonb, 'text', 1, NOW(), NOW()),
  ('aaaa0001-0003-4000-8000-000000003102', 'aaaa0001-0002-4000-8000-000000000031', 'Match family', '{"type":"match_pairs","instruction":"Match the word and translation","pairs":[{"left":"mother","right":"мама"},{"left":"father","right":"папа"},{"left":"brother","right":"брат"},{"left":"sister","right":"сестра"},{"left":"parents","right":"родители"}]}'::jsonb, 'match_pairs', 2, NOW(), NOW()),
  ('aaaa0001-0003-4000-8000-000000003103', 'aaaa0001-0002-4000-8000-000000000031', 'Sibling', '{"type":"fill_blank","instruction":"Complete the sentence","sentence_template":"She is my ___.","options":["sister","brother","father","son"],"correct_answer":"sister","alternatives":[],"explanation":""}'::jsonb, 'fill_blank', 3, NOW(), NOW()),
